var e={S1:JSON.parse(`{"title":"Hören","heading":"Hör, was die Mikrofone wirklich senden","goal":"<span class=\\"snd-parts\\"><span class=\\"need\\">KY-037 oder INMP441</span></span>Zwei Mikrofone, zwei Wege hinein. Das <b>INMP441</b> ist digital: eigener Verstärker und 24-Bit-Wandler, Zahlen über I2S. Das KY-037 hat zwei Ausgänge. <b>AO</b> ist die eigene Spannung des Mikrofons: eine winzige Welle auf einem gleichmäßigen <i>Bias</i>. <b>DO</b> ist ein Ja/Nein vom LM393-Komparator, eingestellt mit dem blauen Trimmpoti. S1 tastet AO mit dem DMA des ADC 16 000-mal pro Sekunde ab (kein <code>analogRead()</code> in einer Schleife), zeichnet es als Oszilloskop, zeigt, wo es im Bereich des ADC sitzt, und lässt dich das Poti einstellen. Die <b>Mics</b>-Ansicht stellt beide nebeneinander. Jedes andere Sound-Lab baut darauf auf: Sampler, 4-Sekunden-Ring und Pegelmesser liegen in <code>kit/lib/sound-kit</code>.","goalLine":"Sieh deine Stimme und ein Klatschen als Welle, vergleich die beiden Mikrofone, lies den Bias (oder die Bits) ab und stell den Komparator so ein, dass er nur bei lauten Geräuschen auslöst.","goalCheck":["Das <b>Scope</b> zeigt eine flache Linie, solange du still bist, und eine Welle, wenn du sprichst; ein Pfiff steht still (Trigger an).","Die <b>Bias</b>-Ansicht zeigt den Bias deines Moduls in mV und kein CLIPPING, wenn du nah daran klatschst; du hast <code>atten 6</code> probiert und gesehen, wie die Schrittgröße halbiert wurde.","In der <b>Comparator</b>-Ansicht leuchtet DO bei Klatschen und bleibt dunkel, wenn du normal sprichst: „tuned“.","<code>status</code> sagt <code>16000 Hz measured</code> und <code>DMA overruns 0</code>.","Mit beiden verkabelten Mikrofonen sagt die <b>Mics</b>-Ansicht, um wie viele dB deutlicher das INMP441 ein Wort hört."],"learn":["analoges vs. digitales Mikrofon","I2S","Bias-Spannung","ADC-Dämpfung","kontinuierlicher ADC + DMA","Ringpuffer","6 dB pro Bit, Headroom","Komparator & Hysterese","dBFS"],"pins":{"0":{"role":"VCC"},"1":{"role":"MICS +"},"2":{"role":"AO"},"3":{"role":"BLK"},"4":{"role":"RES"},"5":{"role":"DC"},"6":{"role":"CS"},"7":{"role":"SDA"},"8":{"role":"SCL"},"9":{"role":"AMP VIN"},"10":{"role":"GND"},"11":{"role":"BTN"},"12":{"role":"MICS G"},"13":{"role":"SD"},"14":{"role":"WS"},"15":{"role":"SCK"},"16":{"role":"BCLK"},"17":{"role":"LRC"},"18":{"role":"BOOT"},"19":{"role":"DIN"},"20":{"role":"DO"},"21":{"role":"AMP G"}},"wiring":{"title":"Verkabelung: die Mikrofone und der Lautsprecher (verkabel, was das Lab braucht; der Bildschirm bleibt wie in Lektion 03)","head":["Modul-Pin","ESP32-S3","Hinweise"],"rows":[["KY-037 + · G","3V3","Das analoge Mikrofon. + an den zweiten 3V3-Pin (den ersten hat der Bildschirm), G an GND. <b>Nie 5 V</b>: AO und DO schwingen bis zur Versorgung des Moduls, und die Pins des ESP32-S3 vertragen höchstens 3,3 V."],["KY-037 AO","GPIO 6","Analogausgang: die Spannung des Mikrofons. GPIO 6 ist ADC1-Kanal 5: ADC1 funktioniert weiter, während WLAN an ist, ADC2 nicht."],["KY-037 DO","GPIO 21","Digitalausgang: Der LM393-Komparator meldet high, wenn der Ton lauter ist als die Einstellung des blauen Trimmpotis."],["INMP441 VDD · GND","3V3","Das digitale Mikrofon (I2S). VDD an 3V3 (teil die Steckbrett-Schiene mit dem KY-037), GND an GND. Nur 3,3 V."],["INMP441 L/R","GND","Low = Es spricht im linken Slot, den das Board liest."],["INMP441 SCK","GPIO 40","Der Bit-Takt. Der ESP32 treibt ihn: 16 000 × 64 = 1,024 MHz."],["INMP441 WS","GPIO 41","Word Select: linker Slot / rechter Slot, kippt alle 32 Taktschritte."],["INMP441 SD","GPIO 42","Die Daten, höchstwertiges Bit zuerst. Nach unten gezogen, sodass ein fehlendes Mikrofon als Nullen gelesen wird."],["MAX98357A VIN · GND","5V","Der Lautsprecherverstärker. 5V liefert am meisten (etwa 3 W an 4 Ω); 3V3 geht auch, leiser."],["MAX98357A BCLK","GPIO 39","Bit-Takt des zweiten I2S-Ports (I2S1; das Mikrofon nutzt I2S0, also laufen beide gleichzeitig)."],["MAX98357A LRC","GPIO 38","Word Select (links/rechts)."],["MAX98357A DIN","GPIO 47","Die Samples, 16 Bit."],["MAX98357A GAIN · SD","nichts","Lass beide unverbunden: 9 dB Verstärkung, und er spielt (links + rechts) / 2."],["Lautsprecher (4 Ω, 3 W)","amp + / −","An der Schraubklemme des Verstärkers: die zwei Drähte des JST-PH2.0-Kabels, rot an +."],["Bildschirm (8 Drähte)","wie Lektion 03","Unverändert. Der Taster an GPIO 5 ist optional: Er macht, was BOOT macht."]]},"commands":{"0":{"does":"Baut Lab S1 und schreibt es aufs Board, dann öffne den Monitor mit <code>uv run pio device monitor</code>.","see":"<code>Listening for an INMP441 on the I2S pins...</code>, <code>Microphone: INMP441 (I2S, digital) (mic setting: auto)</code> (oder KY-037), dann <code>Sound lab S1 …</code>, die Befehlsliste und ein Drei-Ton-Hallo aus dem Lautsprecher. Sei eine halbe Sekunde still: <code>- learning the quiet...</code>","fix":"Falsches Mikrofon gewählt: <code>mic inmp441</code> oder <code>mic ky037</code> (gespeichert, startet neu). Kein Hallo: Der Lautsprecher ist optional; prüf VIN und DIN. „Failed to connect“: Halt BOOT gedrückt, tipp auf RST, lass BOOT los und führ es nochmal aus."},"1":{"does":"Welches Mikrofon die Shell nutzt. <code>auto</code> (der Standard) lauscht beim Start 0,3 s nach einem INMP441. In NVS gespeichert (Namespace <code>sound</code>); das Board startet neu.","see":"<code>Microphone: INMP441 (I2S, digital) (mic setting: inmp441)</code>; oben rechts auf dem Bildschirm ein kleines <b>D</b> statt der DO-Lampe.","fix":"Bleibt beim KY-037: Prüf SCK 40, WS 41, SD 42, L/R an GND."},"2":{"does":"Öffnet auch das andere Mikrofon und zeigt beide Spuren, INMP441 oben: die Ruhe jedes Mikrofons in dBFS und wie weit du darüber liegst.","see":"<code>INMP441 hears it 12 dB more clearly</code> (die Zahl hängt von deinem Raum ab); die Spur des KY-037 ist körniger.","fix":"Nur eine Spur: Das andere Mikrofon ist nicht verkabelt. Verkabel es, dann drück RST: S1 sucht es beim Start."},"3":{"does":"Beim INMP441 gibt es keinen DO-Pin: Das Board vergleicht in Software. thresh ist die Linie in dB über der Ruhe (Standard 15), mit 3 dB Hysterese.","see":"<code>- software comparator at 20 dB</code>; in der Comparator-Ansicht überschreiten sie nur Klatscher.","fix":""},"4":{"does":"Die <b>Scope</b>-Ansicht zeichnet die letzten 20 ms. Sprechen macht eine kleine wackelige Welle, ein Klatschen füllt das Feld.","see":"Eine Welle in Rosa; die Skala links wächst auf ±1-5 mV für eine Stimme, ±100 mV und mehr für ein Klatschen.","fix":"Flache Linie, egal was du tust: AO ist nicht an GPIO 6, oder + ist nicht an 3V3 (die Power-LED des Moduls muss leuchten)."},"5":{"does":"Der Sampler, der ADC und der Pegel in Zahlen.","see":"<code>sampler: 16000 Hz asked, 16000 Hz measured · frames dropped 0 · DMA overruns 0</code>, dann <code>ADC: attenuation 12 dB (0-3.1 V) · bias … mV</code>.","fix":"Overruns steigen: Etwas blockiert Kern 0 lange; sag Claude, was sonst noch läuft."},"6":{"does":"Das 0-3,3-V-Lineal, dein Bias und der Ausschlag der letzten 0,1 s.","see":"Eine Bias-Linie irgendwo um 1-2 V und ein Hinweis wie <code>fits in 0-1.75 V: try atten 6 (2x finer)</code>.","fix":"Bias nahe 0 oder 3,3 V: Das Modul hängt an 5 V, oder ein Draht ist locker. Nimm 3V3."},"7":{"does":"Verengt den Bereich des ADC auf 0-1,75 V: Jeder Schritt wird 0,43 mV statt 0,76. (Doppelklick auf Bias schaltet durch 12 → 6 → 2.5 → 0.)","see":"<code>- attenuation 6 dB (0-1.75 V)</code>; auf dem Lineal schrumpft der schattierte Bereich, die Welle sieht im Scope höher aus.","fix":"<code>CLIPPING</code>: Der Bias oder die Welle passt nicht mehr. Geh zurück mit <code>atten 12</code>."},"8":{"does":"Gibt aus, wie du den Komparator einstellst, und springt zur Comparator-Ansicht.","see":"Drei Schritte: still → dreh, bis LED2 gerade ausgeht; klatschen → sie blitzt; nachjustieren.","fix":""},"9":{"does":"Verschiebt die Schwelle des Komparators. Beobachte die DO-Lampe (oben rechts) und den Streifen: Lautstärke oben, DO darunter.","see":"Eingestellt: <code>DO follows the loud moments: tuned</code>, LED2 blitzt bei Klatschen, dunkel beim Sprechen.","fix":"<code>DO always on</code>: Dreh in die andere Richtung. Welche Richtung empfindlicher ist, unterscheidet sich je nach Hersteller."},"10":{"does":"Gibt den Pegel alle 50 ms als Textbalken aus (jedes Sound-Lab hat es). <code>plot off</code> stoppt es.","see":"<code> 23.4 dB |#########          |   | DO 0</code>-Zeilen, die durchlaufen.","fix":""},"11":{"does":"Gibt die neuesten 64 Samples als Zahlen aus (int16 nach Entfernen des Bias; ein ADC-Schritt = 16).","see":"Vier Zeilen mit je 16 kommagetrennten Zahlen, z. B. <code>-32,16,48,…</code>. Füg sie in eine Tabellenkalkulation ein und zeichne ein Liniendiagramm.","fix":""},"12":{"does":"Freeze hält das Bild an (Doppelklick auf Scope oder langer Druck); span setzt die Zeit über den Bildschirm.","see":"<code>scope frozen (freeze again to go on)</code>; mit <code>span 5</code> werden einzelne Wellen eines Pfiffs deutlich.","fix":""}},"panels":{"0":{"title":"Der Sound-Track, Lab für Lab","intro":"Sechs Labs, jedes mit eigener Firmware, alle lesen dasselbe Mikrofon. Wähl eines, um zu sehen, wozu es Schall macht."},"1":{"title":"Von der Luft zu Zahlen","intro":"Acht Stufen zwischen deiner Stimme und einer Zahl, die der Code nutzen kann. Geh sie Schritt für Schritt durch (oder lass es laufen); die Knöpfe rechts erzeugen Geräusche, und jeder Wert unter dem Bild ist live."},"2":{"title":"Analoges Mikrofon, digitales Mikrofon: wie I2S ein Sample trägt","intro":"Das KY-037 gibt dem ESP32 eine Spannung zum Messen; das INMP441 misst selbst und sendet die Zahl. Unten: ein I2S-Frame auf seinen drei Drähten. Geh ihn Tick für Tick durch und sieh, wie ein 24-Bit-Sample ankommt und dann zur 16-Bit-Zahl wird, die jedes Lab nutzt."},"3":{"title":"Wo die Welle im Bereich des ADC sitzt (KY-037)","intro":"Verschieb den Bias und die Lautstärke, ändere die Dämpfung. Der ADC kann nur im schattierten Bereich messen: Außerhalb wird die Welle flach abgeschnitten (Clipping). Ein kleinerer Bereich gibt feinere Schritte, solange die Welle noch hineinpasst."},"4":{"title":"Der Komparator und sein Poti","intro":"Der LM393 vergleicht AO mit der Spannung, die das Poti einstellt. Über der Linie ist DO high (und LED2 am Modul leuchtet). Zieh die gestrichelte Linie (oder den Regler) und beobachte DO: zu tief, und es flattert die ganze Zeit, zu hoch, und selbst ein Klatschen wird verpasst."},"5":{"title":"Was der Bildschirm zeigt","intro":"Fünf Ansichten. Klick = nächste Ansicht, Doppelklick = die Aktion unten links, langer Druck = Freeze. Oben rechts: der Pegelbalken, die DO-Lampe (oder <b>D</b> beim INMP441), Wellen, während der Lautsprecher spielt, und ein roter Punkt, sobald irgendetwas aufnimmt (S4, S8)."}},"steps":["Verkabel das KY-037: + → 3V3 (der zweite Pin), G → GND, AO → GPIO 6, DO → GPIO 21. Der Bildschirm bleibt wie in Lektion 03. Die Power-LED des Moduls leuchtet.","Flash <code>sound-lab-s1</code>, öffne den Monitor, sei eine Sekunde still. <b>Checkpoint 1:</b> die Zeile <code>Mic: AO on GPIO 6 …</code> und eine flache Linie im Scope.","Sprich, pfeif und klatsch nah am Mikrofon. <b>Checkpoint 2:</b> drei verschiedene Wellen; der Pfiff steht still.","Klick zu <b>Bias</b>, lies deinen Bias in mV ab, probier die Dämpfung, die der Hinweis vorschlägt. <b>Checkpoint 3:</b> kein CLIPPING, wenn du 20 cm entfernt klatschst.","Tipp <code>pot</code> und stell den Komparator ein. <b>Checkpoint 4:</b> „tuned“ in der Comparator-Ansicht.","Tipp <code>status</code>. <b>Checkpoint 5:</b> 16000 Hz gemessen, 0 Overruns."],"note":"Beim INMP441 ist die Skala des Scopes in % des Vollausschlags, die Bias-Ansicht wird zu einer Leiter seiner 24 Bits (jedes Bit = 6 dB; wie viele der Ton nutzt, wie viel Headroom bleibt), der Komparator ist Software, und <b>Numbers</b> ergänzt dB SPL. Ehrliche Erwartungen ans KY-037: Es hat keinen Verstärker. Sein AO ist die rohe Spannung der Kapsel, ein paar Millivolt für eine Stimme, also nutzt Sprache nur eine Handvoll der 4096 Schritte des ADC. Das macht es zu einem guten <b>Lautstärke</b>-Sensor (Klatschen, Klopfen, Lärm, Beats) und nur zu einem groben Mikrofon. DO ist ein einzelner Komparator: Ein Klatschen erzeugt dutzende Flanken darauf, während die Welle die Linie kreuzt, also hören die Labs auf AO und nutzen DO für die Hardware-Lampe und als zweite Meinung. Der ADC tastet über ADC1 ab, der weiterläuft, während WLAN an ist (ADC2 nicht)."}`),S2:{title:`Lautstärke`,heading:`Ein Schallpegelmesser für deinen Raum`,goal:`<span class="snd-parts"><span class="need">KY-037 oder INMP441</span><span class="opt">MAX98357A + Lautsprecher (optional)</span></span>Wie laut ist es? Mit dem <b>INMP441</b> zeigt S2 echte <b>dB SPL</b> (sein Datenblatt sagt −26 dBFS bei 94 dB SPL, also RMS dBFS + 111): 30 Flüstern, 60 Sprechen, 85 die Grenze zum Gehörschaden. Mit dem KY-037 zeigt es dB über der Ruhe deines Raums. S2 macht aus den Samples Dezibel, wie es ein Schallpegelmesser tut: <b>fast</b>- (125 ms) oder <b>slow</b>-Glättung (1 s), ein Peak Hold und einen Grundpegel, der deinen Raum lernt. Dann führt es eine Minute Graph, ein Zehn-Minuten-Lärmtagebuch und einen Alarm, der die LED aus Lektion 02 an GPIO 4 leuchten lässt, wenn es zu laut bleibt.`,goalLine:`Lies den Pegel deines Raums ab (in dB SPL mit dem INMP441), sieh den Unterschied zwischen fast und slow, führ ein Tagebuch und löse den Alarm aus (und stell ihn ab).`,goalCheck:[`Der <b>Meter</b> zeigt ungefähr 0, wenn es still ist, 15-25, wenn du sprichst, 40+ für ein Klatschen und sagt, was das grob ist.`,`Mit <code>speed slow</code> beruhigt sich die Zahl; der Peak-Strich fängt ein Klatschen trotzdem.`,`Nach ein paar Minuten gibt <code>diary</code> Zeilen mit low / avg / high aus.`,`Laute Musik eine Sekunde lang färbt die <b>Alarm</b>-Ansicht rot, schaltet die LED an, und ein Tastendruck stellt sie ab.`],learn:[`Dezibel (+6 = ×2)`,`RMS`,`dB SPL braucht eine bekannte Empfindlichkeit`,`unbewertet vs. dBA`,`85-dB-Risikogrenze`,`fast- / slow-Glättung`,`Grundpegel`,`Echo-Schutz`],pins:{0:{role:`VCC`},1:{role:`MICS +`},2:{role:`AO`},3:{role:`BLK`},4:{role:`RES`},5:{role:`DC`},6:{role:`CS`},7:{role:`SDA`},8:{role:`SCL`},9:{role:`AMP VIN`},10:{role:`GND`},11:{role:`BTN`},12:{role:`MICS G`},13:{role:`SD`},14:{role:`WS`},15:{role:`SCK`},16:{role:`BCLK`},17:{role:`LRC`},18:{role:`BOOT`},19:{role:`DIN`},20:{role:`DO`},21:{role:`AMP G`}},wiring:{title:`Verkabelung: die Mikrofone und der Lautsprecher (verkabel, was das Lab braucht; der Bildschirm bleibt wie in Lektion 03)`,head:[`Modul-Pin`,`ESP32-S3`,`Hinweise`],rows:[[`KY-037 + · G`,`3V3`,`Das analoge Mikrofon. + an den zweiten 3V3-Pin (den ersten hat der Bildschirm), G an GND. <b>Nie 5 V</b>: AO und DO schwingen bis zur Versorgung des Moduls, und die Pins des ESP32-S3 vertragen höchstens 3,3 V.`],[`KY-037 AO`,`GPIO 6`,`Analogausgang: die Spannung des Mikrofons. GPIO 6 ist ADC1-Kanal 5: ADC1 funktioniert weiter, während WLAN an ist, ADC2 nicht.`],[`KY-037 DO`,`GPIO 21`,`Digitalausgang: Der LM393-Komparator meldet high, wenn der Ton lauter ist als die Einstellung des blauen Trimmpotis.`],[`INMP441 VDD · GND`,`3V3`,`Das digitale Mikrofon (I2S). VDD an 3V3 (teil die Steckbrett-Schiene mit dem KY-037), GND an GND. Nur 3,3 V.`],[`INMP441 L/R`,`GND`,`Low = Es spricht im linken Slot, den das Board liest.`],[`INMP441 SCK`,`GPIO 40`,`Der Bit-Takt. Der ESP32 treibt ihn: 16 000 × 64 = 1,024 MHz.`],[`INMP441 WS`,`GPIO 41`,`Word Select: linker Slot / rechter Slot, kippt alle 32 Taktschritte.`],[`INMP441 SD`,`GPIO 42`,`Die Daten, höchstwertiges Bit zuerst. Nach unten gezogen, sodass ein fehlendes Mikrofon als Nullen gelesen wird.`],[`MAX98357A VIN · GND`,`5V`,`Der Lautsprecherverstärker. 5V liefert am meisten (etwa 3 W an 4 Ω); 3V3 geht auch, leiser.`],[`MAX98357A BCLK`,`GPIO 39`,`Bit-Takt des zweiten I2S-Ports (I2S1; das Mikrofon nutzt I2S0, also laufen beide gleichzeitig).`],[`MAX98357A LRC`,`GPIO 38`,`Word Select (links/rechts).`],[`MAX98357A DIN`,`GPIO 47`,`Die Samples, 16 Bit.`],[`MAX98357A GAIN · SD`,`nichts`,`Lass beide unverbunden: 9 dB Verstärkung, und er spielt (links + rechts) / 2.`],[`Lautsprecher (4 Ω, 3 W)`,`amp + / −`,`An der Schraubklemme des Verstärkers: die zwei Drähte des JST-PH2.0-Kabels, rot an +.`],[`Bildschirm (8 Drähte)`,`wie Lektion 03`,`Unverändert. Der Taster an GPIO 5 ist optional: Er macht, was BOOT macht.`]]},commands:{0:{does:`Baut Lab S2 und schreibt es aufs Board, dann öffne den Monitor mit <code>uv run pio device monitor</code>.`,see:`<code>Listening for an INMP441 on the I2S pins...</code>, <code>Microphone: INMP441 (I2S, digital) (mic setting: auto)</code> (oder KY-037), dann <code>Sound lab S2 …</code>, die Befehlsliste und ein Drei-Ton-Hallo aus dem Lautsprecher. Sei eine halbe Sekunde still: <code>- learning the quiet...</code>`,fix:`Falsches Mikrofon gewählt: <code>mic inmp441</code> oder <code>mic ky037</code> (gespeichert, startet neu). Kein Hallo: Der Lautsprecher ist optional; prüf VIN und DIN. „Failed to connect“: Halt BOOT gedrückt, tipp auf RST, lass BOOT los und führ es nochmal aus.`},1:{does:`Die <b>Meter</b>-Ansicht: Die große Zahl sind dB über der Ruhe deines Raums.`,see:`Etwa 15-25, während du sprichst („talking“), 40+ bei einem Klatschen („shout, clap, bang“). Der weiße Strich ist der Peak Hold.`,fix:`Immer 0: Die Ruhe wurde gelernt, während du gesprochen hast. Tipp <code>quiet</code> und sei eine halbe Sekunde still.`},2:{does:`Schaltet Meter, Graphen und Alarm auf 1-s-Glättung (Doppelklick auf Meter schaltet um).`,see:`<code>- slow: 1 s smoothing</code>; die Zahl bewegt sich ruhig, ein Klatschen hebt sie kaum.`,fix:``},3:{does:`Schaltet zwischen dB SPL (nur INMP441) und dB über der Ruhe um.`,see:`<code>- units: dB above the quiet</code>; <code>units spl</code> am KY-037: <code>dB SPL needs the INMP441 (its sensitivity is known)</code>.`,fix:``},4:{does:`Die Alarmlinie: 30-120 dB SPL (Standard 80) oder 3-60 dB über der Ruhe (Standard 35). In NVS gespeichert (Namespace <code>loud</code>).`,see:`<code>- limit 75 dB SPL</code>; die gepunktete rote Linie wandert.`,fix:``},5:{does:`Die Alarm-Melodie spielt einmal pro Alarm auf dem Lautsprecher (der Taster stoppt sie auch). Der Echo-Schutz verhindert, dass S2 seine eigene Melodie misst.`,see:`<code>- alarm sound off</code>.`,fix:``},6:{does:`Über dem Limit für <code>hold</code> (1 s) löst den Alarm aus.`,see:`<code>x too loud: 38 dB</code>; die <b>Alarm</b>-Ansicht pulst rot, die LED an GPIO 4 leuchtet (wenn verkabelt).`,fix:`Kein Alarm: <code>alarm on</code> oder ein niedrigeres <code>limit</code>.`},7:{does:`Solange der Alarm klingelt, stellt ihn jeder Tastendruck ab; er schärft sich neu, wenn der Raum ruhig ist (3 dB unter der Linie).`,see:`<code>- alarm silenced</code>, später <code>+ calm again</code>.`,fix:``},8:{does:`Gibt die letzten zehn Minuten aus, eine Zeile pro 10 s: leisester, durchschnittlicher, lautester Wert und ALARM.`,see:`<code>  60s     2   11   34  |=====      |</code>-Zeilen.`,fix:`Leer: Das Tagebuch füllt alle 10 s eine Zeile. Komm in ein paar Minuten wieder.`}},panels:{0:{title:`Was ein Dezibel ist`,intro:`Unsere Ohren hören Verhältnisse, keine Differenzen, also wird Lautstärke in Dezibel gemessen: 20 × log10(das ÷ die Ruhe). Verschieb die Lautstärke und sieh die Welle: Jedes +6 dB verdoppelt ihre Höhe, +20 dB ist das Zehnfache.`},1:{title:`Fast, slow und der Grundpegel`,intro:`Derselbe Ton durch die drei Linsen des Meters, wiedergegeben. Wähl eine Szene. Der Grundpegel folgt der Ruhe: Er fällt sofort und kriecht 0,5 dB pro Sekunde hoch, also wird ein Lüfter, der weiterläuft, zur neuen Ruhe.`},2:{title:`Was der Bildschirm zeigt`,intro:`Vier Ansichten. Klick = nächste, Doppelklick = die Aktion unten links (speed, quiet, diary, alarm), langer Druck = Ruhe neu lernen. Solange der Alarm klingelt, stellt ihn jeder Tastendruck ab.`}},steps:[`Gleiche Verkabelung wie S1. Optional: die LED aus Lektion 02 an GPIO 4 über ihren Widerstand (das Alarmlicht).`,`Flash <code>sound-lab-s2</code> und sei eine Sekunde still. <b>Checkpoint 1:</b> Der Meter zeigt 0-3 dB, „quiet“.`,`Sprich in normaler Stimme aus 30 cm Entfernung. <b>Checkpoint 2:</b> 15-25 dB, „talking“.`,`<code>speed slow</code>, dann <code>speed fast</code>. <b>Checkpoint 3:</b> Du kannst den Unterschied beschreiben.`,`Spiel laut Musik nah am Mikrofon. <b>Checkpoint 4:</b> TOO LOUD in der Alarm-Ansicht, dann stell ihn mit dem Taster ab.`,`Lass es zehn Minuten laufen, dann <code>diary</code>. <b>Checkpoint 5:</b> eine Tabelle der zehn Minuten deines Raums.`],note:`dB SPL braucht ein Mikrofon mit bekannter Empfindlichkeit: Die des INMP441 steht in seinem Datenblatt, also kann S2 es zeigen (unbewertet, etwa ±2 dB; echte Messgeräte zeigen oft dBA, das die Frequenzen wie das Ohr gewichtet und bei einem tiefen Brummen niedriger liest). Die Zahlen des KY-037 sind dB über der Ruhe <i>deines</i> Raums, nicht dB SPL (die Zahl, die ein kalibriertes Messgerät zeigt): Dafür bräuchte man ein Referenzmikrofon und die Empfindlichkeit der Kapsel. Der Grundpegel wird in der ersten halben Sekunde nach dem Boot oder <code>quiet</code> gelernt und folgt dann der Ruhe (sofort runter, 0,5 dB/s hoch). Einstellungen (speed, limit, hold, alarm) überleben einen Reset in NVS; das Tagebuch nicht.`},S3:{title:`Klatschsteuerung`,heading:`Schalte Dinge mit deinen Händen`,goal:`<span class="snd-parts"><span class="need">KY-037 oder INMP441</span><span class="opt">MAX98357A + Lautsprecher (optional)</span></span>Ein Klatschen schaltet die LED um, zwei ändern die RGB-Farbe, drei schicken den Bildschirm schlafen, vier schmeißen eine Party. Eine Stimme, ein Pfiff oder Musik zählt nie: Ein Klatschen ist nicht nur laut, es hat eine <b>Form</b> (ein Sprung innerhalb von 4 ms, vorbei innerhalb von 160 ms). Klatscher dicht nacheinander bilden ein Muster; eine Pause von 0,65 s beendet es. Was jedes Muster tut, ist eine Zuordnung in NVS, die du ändern kannst, und jede Aktion antwortet mit einem eigenen kleinen Ton auf dem Lautsprecher.`,goalLine:`Lass 1, 2, 3 und 4 Klatscher vier verschiedene Dinge tun, beweise, dass Sprechen sie nicht auslöst, und stimm den Detektor auf deine eigenen Klatscher ab.`,goalCheck:[`Ein Klatschen schaltet die LED an GPIO 4 um (oder gibt <code>LED on</code> aus), zwei ändern die RGB-Farbe.`,`Auf der <b>Timeline</b> bekommt ein Klatschen eine türkise Fahne, ein gesprochenes Wort einen bernsteinfarbenen <i>long</i>-Balken, und nichts passiert.`,`<code>learn</code> + 5 Klatscher setzen <code>sens</code> aus deinem leisesten Klatschen.`,`Du hast ein Muster mit <code>map</code> neu belegt, und es hat einen Reset überlebt.`],learn:[`Onset-Erkennung`,`die Form eines Klatschens`,`Hysterese`,`Gruppierung in der Zeit`,`Kalibrierung aus Daten`,`NVS-Zuordnung`,`Klang als Feedback`,`Echo-Schutz`],pins:{0:{role:`VCC`},1:{role:`MICS +`},2:{role:`AO`},3:{role:`BLK`},4:{role:`RES`},5:{role:`DC`},6:{role:`CS`},7:{role:`SDA`},8:{role:`SCL`},9:{role:`AMP VIN`},10:{role:`GND`},11:{role:`BTN`},12:{role:`MICS G`},13:{role:`SD`},14:{role:`WS`},15:{role:`SCK`},16:{role:`BCLK`},17:{role:`LRC`},18:{role:`BOOT`},19:{role:`DIN`},20:{role:`DO`},21:{role:`AMP G`}},wiring:{title:`Verkabelung: die Mikrofone und der Lautsprecher (verkabel, was das Lab braucht; der Bildschirm bleibt wie in Lektion 03)`,head:[`Modul-Pin`,`ESP32-S3`,`Hinweise`],rows:[[`KY-037 + · G`,`3V3`,`Das analoge Mikrofon. + an den zweiten 3V3-Pin (den ersten hat der Bildschirm), G an GND. <b>Nie 5 V</b>: AO und DO schwingen bis zur Versorgung des Moduls, und die Pins des ESP32-S3 vertragen höchstens 3,3 V.`],[`KY-037 AO`,`GPIO 6`,`Analogausgang: die Spannung des Mikrofons. GPIO 6 ist ADC1-Kanal 5: ADC1 funktioniert weiter, während WLAN an ist, ADC2 nicht.`],[`KY-037 DO`,`GPIO 21`,`Digitalausgang: Der LM393-Komparator meldet high, wenn der Ton lauter ist als die Einstellung des blauen Trimmpotis.`],[`INMP441 VDD · GND`,`3V3`,`Das digitale Mikrofon (I2S). VDD an 3V3 (teil die Steckbrett-Schiene mit dem KY-037), GND an GND. Nur 3,3 V.`],[`INMP441 L/R`,`GND`,`Low = Es spricht im linken Slot, den das Board liest.`],[`INMP441 SCK`,`GPIO 40`,`Der Bit-Takt. Der ESP32 treibt ihn: 16 000 × 64 = 1,024 MHz.`],[`INMP441 WS`,`GPIO 41`,`Word Select: linker Slot / rechter Slot, kippt alle 32 Taktschritte.`],[`INMP441 SD`,`GPIO 42`,`Die Daten, höchstwertiges Bit zuerst. Nach unten gezogen, sodass ein fehlendes Mikrofon als Nullen gelesen wird.`],[`MAX98357A VIN · GND`,`5V`,`Der Lautsprecherverstärker. 5V liefert am meisten (etwa 3 W an 4 Ω); 3V3 geht auch, leiser.`],[`MAX98357A BCLK`,`GPIO 39`,`Bit-Takt des zweiten I2S-Ports (I2S1; das Mikrofon nutzt I2S0, also laufen beide gleichzeitig).`],[`MAX98357A LRC`,`GPIO 38`,`Word Select (links/rechts).`],[`MAX98357A DIN`,`GPIO 47`,`Die Samples, 16 Bit.`],[`MAX98357A GAIN · SD`,`nichts`,`Lass beide unverbunden: 9 dB Verstärkung, und er spielt (links + rechts) / 2.`],[`Lautsprecher (4 Ω, 3 W)`,`amp + / −`,`An der Schraubklemme des Verstärkers: die zwei Drähte des JST-PH2.0-Kabels, rot an +.`],[`Bildschirm (8 Drähte)`,`wie Lektion 03`,`Unverändert. Der Taster an GPIO 5 ist optional: Er macht, was BOOT macht.`]]},commands:{0:{does:`Baut Lab S3 und schreibt es aufs Board, dann öffne den Monitor mit <code>uv run pio device monitor</code>.`,see:`<code>Listening for an INMP441 on the I2S pins...</code>, <code>Microphone: INMP441 (I2S, digital) (mic setting: auto)</code> (oder KY-037), dann <code>Sound lab S3 …</code>, die Befehlsliste und ein Drei-Ton-Hallo aus dem Lautsprecher. Sei eine halbe Sekunde still: <code>- learning the quiet...</code>`,fix:`Falsches Mikrofon gewählt: <code>mic inmp441</code> oder <code>mic ky037</code> (gespeichert, startet neu). Kein Hallo: Der Lautsprecher ist optional; prüf VIN und DIN. „Failed to connect“: Halt BOOT gedrückt, tipp auf RST, lass BOOT los und führ es nochmal aus.`},1:{does:`Ein Klatschen = <code>led</code>, zwei = <code>colour</code> (die Standardwerte; drei = <code>screen</code>, vier = <code>party</code>).`,see:`<code>- 1 clap -> led</code>, <code>+ LED on</code>; dann <code>- 2 claps -> colour</code>, <code>+ colour: warm white</code>. Die <b>Lamp</b>-Ansicht zeigt beides.`,fix:`Nichts: Die Klatscher sind zu leise für <code>sens</code> 18 dB. Probier <code>learn</code>.`},2:{does:`Gibt jedes Klatschen, jeden langen Ton und jede Gruppe aus, sobald sie passieren.`,see:`<code>  clap at 5120 ms: 31.0 dB, 48 ms long</code>, <code>  LONG (not a clap) at …: 22.0 dB, 380 ms long</code>, <code>  group of 2: gaps 290 ms</code>.`,fix:`<code>test off</code> zum Stoppen.`},3:{does:`Springt zu <b>Tune</b>: Klatsch 5-mal, so wie du es normalerweise tust. sens wird 60 % des leisesten (zwischen 8 und 40 dB), gespeichert.`,see:`<code>- clap 1 of 5: 29 dB</code> … <code>+ learnt: sens 17 dB (saved)</code>; fünf Balken mit ihren dB und ms.`,fix:`Sprechen während learn wird unter <i>long (voice?)</i> gezählt, nicht als Klatschen.`},4:{does:`Drei Klatscher spielen jetzt twinkle auf dem Lautsprecher. Aktionen: led colour dark screen view party tune none.`,see:`<code>+ 3 claps -> tune (saved)</code>; <code>maps</code> gibt alle vier aus.`,fix:``},5:{does:`Jede Aktion antwortet mit einem Ton: LED hoch/runter, ein Farb-Arpeggio, ein Klick für screen und view, eine Fanfare für die Party, ein tiefes Nein, wenn ein Muster nicht belegt ist. <code>sound off</code> schaltet sie ab (gespeichert).`,see:`<code>+ pattern sounds off (saved)</code>.`,fix:``},6:{does:`Eine kürzere Pause beendet ein Muster: flotter, aber langsame Klatscher werden in zwei Muster zerteilt.`,see:`<code>+ pause 400 ms ends a pattern (saved)</code>.`,fix:``},7:{does:`Führt eine Aktion ohne Klatschen aus (um die Verkabelung zu testen).`,see:`<code>+ party!</code>, 2 s Regenbogen auf der RGB-LED.`,fix:``}},panels:{0:{title:`Ist das ein Klatschen? Der Detektor, 4 ms auf einmal`,intro:`Dieselben Regeln wie in kit/lib/sound-kit/src/onsets.h, auf einem Ton deiner Wahl ausgeführt. Geh einen Frame nach dem anderen oder spiel es ab, verschieb die Anstiegs- und Abfalllinien. Scharf → laut (ONSET) → leise (CLAP, wenn es kurz war, LONG, wenn nicht) → nach 40 ms Ruhe wieder scharf.`},1:{title:`Was der Bildschirm zeigt`,intro:`Vier Ansichten. Klick = nächste, Doppelklick = die Aktion unten links (test, colour, maps, learn), langer Druck = learn.`}},steps:[`Gleiche Verkabelung wie S1. Optional: die LED aus Lektion 02 an GPIO 4.`,`Flash <code>sound-lab-s3</code>, sei eine Sekunde still. <b>Checkpoint 1:</b> Die <b>Timeline</b> zeigt eine flache Linie mit den Anstiegs- und Abfalllinien.`,`Klatsch einmal, dann zweimal. <b>Checkpoint 2:</b> Die LED schaltet um, RGB wechselt die Farbe.`,`Sprich normal neben dem Mikrofon. <b>Checkpoint 3:</b> bernsteinfarbene <i>long</i>-Balken, keine Aktion.`,`<code>learn</code>, klatsch 5-mal. <b>Checkpoint 4:</b> ein neues <code>sens</code>, gespeichert.`,`<code>map 1 party</code>, klatsch einmal, setz das Board zurück, klatsch nochmal. <b>Checkpoint 5:</b> immer noch eine Party.`],note:`Die eigenen Töne des Boards zählen nie als Klatschen: Solange der Lautsprecher spielt (und 200 ms danach), bekommt der Detektor keine Frames, der Echo-Schutz. Fünf oder mehr Klatscher hintereinander zählen als Applaus und tun nichts. Drei Klatscher schalten die Hintergrundbeleuchtung aus: Sie kommt nach 30 s oder mit jedem Tastendruck zurück, sodass der Bildschirm nicht verloren gehen kann. Der Detektor hört AO über den Pegelmesser, nicht DO: Ein Klatschen erzeugt dutzende DO-Flanken.`},S4:{title:`Recorder`,heading:`Ein sprachgesteuerter Rekorder`,goal:`<span class="snd-parts"><span class="need">KY-037 oder INMP441</span><span class="opt">WLAN (W1) (optional)</span><span class="opt">MAX98357A + Lautsprecher (optional)</span></span>Scharf geschaltet wartet das Board auf einen Ton, der lauter ist als der Trigger, und nimmt dann ins PSRAM auf, beginnend eine halbe Sekunde <i>vor</i> dem Trigger (der Ringpuffer hat es noch), bis 1,2 s Ruhe. Bis zu 12 Clips, 6 MB, nach einem Reset weg. Hör sie auf deinem Handy unter <code>http://bench.local</code> (das WLAN-Netz, das W1 gespeichert hat, plus das Admin-Token), zieh eine WAV per USB mit <code>tools/sound_pull.py</code> oder spiel sie auf dem eigenen Lautsprecher des Boards ab (<code>play 3 0.7</code>: langsamer und tiefer). Das Board zeigt immer REC und eine rote LED, solange es aufnimmt, egal wer es gestartet hat.`,goalLine:`Nimm einen Satz freihändig auf, sieh den Pre-Roll, spiel ihn auf deinem Handy ab und zieh einen Clip als WAV-Datei auf deinen Mac.`,goalCheck:[`<code>arm</code>, dann sprich: Die <b>Recorder</b>-Ansicht geht ARMED → REC → ARMED, und <code>clips</code> listet einen Voice-Clip.`,`Ein Türknall oder ein einzelnes Klatschen startet eine Aufnahme, wird aber verworfen (zu kurz).`,`Die Handy-Seite unter <code>http://bench.local</code> entsperrt sich mit dem Token, zeichnet den Clip und spielt ihn ab.`,`<code>tools/sound_pull.py</code> hat eine .wav geschrieben, die auf dem Mac abspielt.`,`<code>play</code> (oder ein Doppelklick auf <b>Clips</b>) spielt den gewählten Clip auf dem Lautsprecher des Boards ab; <code>play 1 2</code> ist ein Chipmunk.`],learn:[`Pre-Roll aus einem Ring`,`Trigger + Hold`,`PSRAM-Clipspeicher`,`WAV-Format`,`Streaming-Antworten`,`Base64 + CRC-32`,`Abspielgeschwindigkeit = Tonhöhe`,`Token & sichtbare Aufnahme`],pins:{0:{role:`VCC`},1:{role:`MICS +`},2:{role:`AO`},3:{role:`BLK`},4:{role:`RES`},5:{role:`DC`},6:{role:`CS`},7:{role:`SDA`},8:{role:`SCL`},9:{role:`AMP VIN`},10:{role:`GND`},11:{role:`BTN`},12:{role:`MICS G`},13:{role:`SD`},14:{role:`WS`},15:{role:`SCK`},16:{role:`BCLK`},17:{role:`LRC`},18:{role:`BOOT`},19:{role:`DIN`},20:{role:`DO`},21:{role:`AMP G`}},wiring:{title:`Verkabelung: die Mikrofone und der Lautsprecher (verkabel, was das Lab braucht; der Bildschirm bleibt wie in Lektion 03)`,head:[`Modul-Pin`,`ESP32-S3`,`Hinweise`],rows:[[`KY-037 + · G`,`3V3`,`Das analoge Mikrofon. + an den zweiten 3V3-Pin (den ersten hat der Bildschirm), G an GND. <b>Nie 5 V</b>: AO und DO schwingen bis zur Versorgung des Moduls, und die Pins des ESP32-S3 vertragen höchstens 3,3 V.`],[`KY-037 AO`,`GPIO 6`,`Analogausgang: die Spannung des Mikrofons. GPIO 6 ist ADC1-Kanal 5: ADC1 funktioniert weiter, während WLAN an ist, ADC2 nicht.`],[`KY-037 DO`,`GPIO 21`,`Digitalausgang: Der LM393-Komparator meldet high, wenn der Ton lauter ist als die Einstellung des blauen Trimmpotis.`],[`INMP441 VDD · GND`,`3V3`,`Das digitale Mikrofon (I2S). VDD an 3V3 (teil die Steckbrett-Schiene mit dem KY-037), GND an GND. Nur 3,3 V.`],[`INMP441 L/R`,`GND`,`Low = Es spricht im linken Slot, den das Board liest.`],[`INMP441 SCK`,`GPIO 40`,`Der Bit-Takt. Der ESP32 treibt ihn: 16 000 × 64 = 1,024 MHz.`],[`INMP441 WS`,`GPIO 41`,`Word Select: linker Slot / rechter Slot, kippt alle 32 Taktschritte.`],[`INMP441 SD`,`GPIO 42`,`Die Daten, höchstwertiges Bit zuerst. Nach unten gezogen, sodass ein fehlendes Mikrofon als Nullen gelesen wird.`],[`MAX98357A VIN · GND`,`5V`,`Der Lautsprecherverstärker. 5V liefert am meisten (etwa 3 W an 4 Ω); 3V3 geht auch, leiser.`],[`MAX98357A BCLK`,`GPIO 39`,`Bit-Takt des zweiten I2S-Ports (I2S1; das Mikrofon nutzt I2S0, also laufen beide gleichzeitig).`],[`MAX98357A LRC`,`GPIO 38`,`Word Select (links/rechts).`],[`MAX98357A DIN`,`GPIO 47`,`Die Samples, 16 Bit.`],[`MAX98357A GAIN · SD`,`nichts`,`Lass beide unverbunden: 9 dB Verstärkung, und er spielt (links + rechts) / 2.`],[`Lautsprecher (4 Ω, 3 W)`,`amp + / −`,`An der Schraubklemme des Verstärkers: die zwei Drähte des JST-PH2.0-Kabels, rot an +.`],[`Bildschirm (8 Drähte)`,`wie Lektion 03`,`Unverändert. Der Taster an GPIO 5 ist optional: Er macht, was BOOT macht.`]]},commands:{0:{does:`Baut Lab S4 und schreibt es aufs Board, dann öffne den Monitor mit <code>uv run pio device monitor</code>.`,see:`<code>Listening for an INMP441 on the I2S pins...</code>, <code>Microphone: INMP441 (I2S, digital) (mic setting: auto)</code> (oder KY-037), dann <code>Sound lab S4 …</code>, die Befehlsliste und ein Drei-Ton-Hallo aus dem Lautsprecher. Sei eine halbe Sekunde still: <code>- learning the quiet...</code>`,fix:`Falsches Mikrofon gewählt: <code>mic inmp441</code> oder <code>mic ky037</code> (gespeichert, startet neu). Kein Hallo: Der Lautsprecher ist optional; prüf VIN und DIN. „Failed to connect“: Halt BOOT gedrückt, tipp auf RST, lass BOOT los und führ es nochmal aus.`},1:{does:`Sprachgesteuert: lauter als <code>trigger</code> (15 dB über der Ruhe) startet einen Clip.`,see:`<code>- armed: talk and it records</code>; die <b>Recorder</b>-Ansicht sagt ARMED (türkiser Ring).`,fix:``},2:{does:`Nimmt von einer halben Sekunde vor deinem ersten Wort bis 1,2 s nach dem letzten lauten Moment auf.`,see:`<code>x REC clip 1 (voice)</code>; REC 2.4 s in Rot, der rote Punkt im Kopf, die RGB-LED rot; dann <code>+ clip 1: 3.1 s</code>.`,fix:`Startet nie: Sprich näher heran oder <code>trigger 10</code>.`},3:{does:`Spielt Clip 1 auf dem Lautsprecher des Boards mit 0,7-facher Geschwindigkeit ab (tiefer, langsamer). Ohne Zahl: der in der <b>Clips</b>-Ansicht gewählte Clip. Wie beim Download lauter gemacht, aber höchstens ×16. <code>stop</code> stoppt es; <code>rec</code> stoppt es vor der Aufnahme; während der Aufnahme wird es abgelehnt.`,see:`<code>+ playing clip 1 (4.4 s) at x0.70</code>, dann <code>- clip 1 played</code>; Wellen im Kopf.`,fix:`<code>recording: stop first (the microphone would hear the speaker)</code>.`},4:{does:`Listet die Clips: Nummer, Länge, Stimme oder Hand, lautester Wert, um wie viel lauter gesendet, wann.`,see:`<code>    1    3.1s  voice  -38.2 dBFS  x23.4  2026-10-14 14:02:31</code>`,fix:``},5:{does:`Gibt das Admin-Token aus, nach dem die Handy-Seite fragt (geteilt mit W2/R7/R8).`,see:`<code>Admin token: 3f…</code> und wohin du es einfügst.`,fix:`Halt es aus Chats und Git heraus; <code>token new</code> ersetzt es.`},6:{does:`Die eigene Seite des Boards: Live-Pegel, arm / rec / stop, die Clipliste mit jeder Wellenform, Abspielen und Download, eine Geschwindigkeitswahl und <b>Play on board</b> / <b>Stop on board</b> pro Clip. Das Token bleibt nur in diesem Tab.`,see:`Eine Clip-Karte mit ihrer Form; Abspielen bewegt einen Playhead.`,fix:`„no Wi-Fi saved“: Flash wifi-lab-w1 einmal und verbinde dich. Seite nicht erreichbar: dasselbe Netz? Probier die IP aus <code>wifi</code>.`},7:{does:`Schließ zuerst den Monitor. Tippt <code>send 1</code>, liest die Base64-WAV, prüft den CRC-32 und die Größe, schreibt die Datei.`,see:`<code>Receiving clip 1: 99244 bytes as …</code>, dann <code>Saved … (3.1 s at 16000 Hz, 99244 bytes, CRC ok)</code>.`,fix:`<code>Could not open … (is the serial monitor still open?)</code>: Schließ ihn.`}},panels:{0:{title:`Sprachgesteuerte Aufnahme, Schritt für Schritt`,intro:`Neun Sekunden: ein Türknall, dann ein Satz mit einer Pause. Geh Schritt für Schritt oder spiel ab, verschieb Trigger und Hold. Bernstein = der Pre-Roll aus dem Ring, Rot = aufgenommen, Grau = verworfen.`},1:{title:`Das Audio herausbekommen`,intro:`Drei Wege: das Handy über WLAN, der Mac über den seriellen USB-Port oder der eigene Lautsprecher des Boards. Unten: die 44 Bytes, mit denen jede WAV-Datei beginnt (für einen 3,2-s-Clip bei 16 000 Hz).`},2:{title:`Was der Bildschirm zeigt`,intro:`Drei Ansichten. Klick = nächste, Doppelklick = die Aktion unten links (arm, next, wifi), langer Druck = rec / stop.`}},steps:[`Gleiche Verkabelung wie S1. Das Board braucht das gespeicherte WLAN-Netz von W1 (nur für die Handy-Seite).`,`Flash <code>sound-lab-s4</code>. <b>Checkpoint 1:</b> OFF in der Recorder-Ansicht und <code>page: http://bench.local</code>, sobald das WLAN verbunden ist.`,`<code>arm</code>, sag einen Satz. <b>Checkpoint 2:</b> ein Clip; der bernsteinfarbene Pre-Roll vor deinem ersten Wort.`,`Klatsch einmal. <b>Checkpoint 3:</b> <code>a bang, not a voice: clip 2 dropped</code>.`,`Öffne die Seite auf deinem Handy, füg das <code>token</code> ein. <b>Checkpoint 4:</b> Dein Clip spielt.`,`Schließ den Monitor, führ <code>tools/sound_pull.py</code> aus. <b>Checkpoint 5:</b> eine .wav auf deinem Mac.`],note:`Datenschutz ist eingebaut, nicht optional: Aufnahme zeigt sich immer am Board (REC, roter Punkt, rote LED), egal wer sie startet; jeder Audioweg auf der Seite braucht das Admin-Token; Clips liegen nur im RAM und verschwinden beim Reset. Der Klang wird dünn und rauschig sein: Die Clips werden auf dem Weg nach draußen normalisiert (bis zu 64-mal lauter gemacht), und das hebt das Rauschen mit der Stimme. Dieses Modul ist zuerst ein Lautstärke-Sensor, dann ein Mikrofon.`},S5:{title:`Spektrum`,heading:`Sieh, welche Frequenzen in einem Ton stecken`,goal:`<span class="snd-parts"><span class="need">KY-037 oder INMP441</span><span class="opt">MAX98357A + Lautsprecher (optional)</span></span>Unsere eigene FFT (keine Bibliothek) läuft etwa 25-mal pro Sekunde auf den neuesten 512 Samples: Balken von 100 Hz bis 8 kHz, ein scrollendes Wasserfall-Diagramm, ein Tuner, der die Note benennt, die du pfeifst oder summst, und ein Spiel, das du mit der Tonhöhe deines Pfiffs steuerst. Mit dem Lautsprecher prüft sich das Board selbst: <code>ref</code> spielt eine Referenznote für den Tuner, <code>sweep</code> klettert über die Balken von 100 Hz auf 8 kHz.`,goalLine:`Finde die Frequenz deines Pfiffs, sieh, warum feinere Bins langsamer sind, und punkte im Steer-Spiel.`,goalCheck:[`Die <b>Bars</b>-Ansicht zeigt einen einzelnen hohen Balken, wenn du pfeifst, und viele niedrige, wenn du sprichst.`,`Der <b>Tuner</b> nennt deine Note, und die Nadel wird innerhalb von ±5 Cent türkis.`,`<code>fft 1024</code> und <code>fft 256</code>: Du kannst sagen, was sich geändert hat (Hz pro Bin, wie schnell es reagiert).`,`<b>Steer</b>: Du hast mindestens 3 Ziele erreicht.`],learn:[`FFT-Bins`,`Hann-Fenster & Leakage`,`Nyquist (8 kHz)`,`Auflösung vs. Tempo`,`logarithmische Frequenz`,`Noten & Cent`,`Referenztöne`,`logarithmischer Sweep`],pins:{0:{role:`VCC`},1:{role:`MICS +`},2:{role:`AO`},3:{role:`BLK`},4:{role:`RES`},5:{role:`DC`},6:{role:`CS`},7:{role:`SDA`},8:{role:`SCL`},9:{role:`AMP VIN`},10:{role:`GND`},11:{role:`BTN`},12:{role:`MICS G`},13:{role:`SD`},14:{role:`WS`},15:{role:`SCK`},16:{role:`BCLK`},17:{role:`LRC`},18:{role:`BOOT`},19:{role:`DIN`},20:{role:`DO`},21:{role:`AMP G`}},wiring:{title:`Verkabelung: die Mikrofone und der Lautsprecher (verkabel, was das Lab braucht; der Bildschirm bleibt wie in Lektion 03)`,head:[`Modul-Pin`,`ESP32-S3`,`Hinweise`],rows:[[`KY-037 + · G`,`3V3`,`Das analoge Mikrofon. + an den zweiten 3V3-Pin (den ersten hat der Bildschirm), G an GND. <b>Nie 5 V</b>: AO und DO schwingen bis zur Versorgung des Moduls, und die Pins des ESP32-S3 vertragen höchstens 3,3 V.`],[`KY-037 AO`,`GPIO 6`,`Analogausgang: die Spannung des Mikrofons. GPIO 6 ist ADC1-Kanal 5: ADC1 funktioniert weiter, während WLAN an ist, ADC2 nicht.`],[`KY-037 DO`,`GPIO 21`,`Digitalausgang: Der LM393-Komparator meldet high, wenn der Ton lauter ist als die Einstellung des blauen Trimmpotis.`],[`INMP441 VDD · GND`,`3V3`,`Das digitale Mikrofon (I2S). VDD an 3V3 (teil die Steckbrett-Schiene mit dem KY-037), GND an GND. Nur 3,3 V.`],[`INMP441 L/R`,`GND`,`Low = Es spricht im linken Slot, den das Board liest.`],[`INMP441 SCK`,`GPIO 40`,`Der Bit-Takt. Der ESP32 treibt ihn: 16 000 × 64 = 1,024 MHz.`],[`INMP441 WS`,`GPIO 41`,`Word Select: linker Slot / rechter Slot, kippt alle 32 Taktschritte.`],[`INMP441 SD`,`GPIO 42`,`Die Daten, höchstwertiges Bit zuerst. Nach unten gezogen, sodass ein fehlendes Mikrofon als Nullen gelesen wird.`],[`MAX98357A VIN · GND`,`5V`,`Der Lautsprecherverstärker. 5V liefert am meisten (etwa 3 W an 4 Ω); 3V3 geht auch, leiser.`],[`MAX98357A BCLK`,`GPIO 39`,`Bit-Takt des zweiten I2S-Ports (I2S1; das Mikrofon nutzt I2S0, also laufen beide gleichzeitig).`],[`MAX98357A LRC`,`GPIO 38`,`Word Select (links/rechts).`],[`MAX98357A DIN`,`GPIO 47`,`Die Samples, 16 Bit.`],[`MAX98357A GAIN · SD`,`nichts`,`Lass beide unverbunden: 9 dB Verstärkung, und er spielt (links + rechts) / 2.`],[`Lautsprecher (4 Ω, 3 W)`,`amp + / −`,`An der Schraubklemme des Verstärkers: die zwei Drähte des JST-PH2.0-Kabels, rot an +.`],[`Bildschirm (8 Drähte)`,`wie Lektion 03`,`Unverändert. Der Taster an GPIO 5 ist optional: Er macht, was BOOT macht.`]]},commands:{0:{does:`Baut Lab S5 und schreibt es aufs Board, dann öffne den Monitor mit <code>uv run pio device monitor</code>.`,see:`<code>Listening for an INMP441 on the I2S pins...</code>, <code>Microphone: INMP441 (I2S, digital) (mic setting: auto)</code> (oder KY-037), dann <code>Sound lab S5 …</code>, die Befehlsliste und ein Drei-Ton-Hallo aus dem Lautsprecher. Sei eine halbe Sekunde still: <code>- learning the quiet...</code>`,fix:`Falsches Mikrofon gewählt: <code>mic inmp441</code> oder <code>mic ky037</code> (gespeichert, startet neu). Kein Hallo: Der Lautsprecher ist optional; prüf VIN und DIN. „Failed to connect“: Halt BOOT gedrückt, tipp auf RST, lass BOOT los und führ es nochmal aus.`},1:{does:`Die <b>Bars</b>-Ansicht: ein hoher Balken für einen Pfiff (1-3 kHz), niedriger und breiter für ein Summen.`,see:`<code>loudest 1.76 kHz (A6)</code> oben; rechts: <code>N 512 - 31 Hz/bin - … us</code>.`,fix:`Nichts bewegt sich: Pfeif auf Handbreite Abstand (das Modul hat keinen Verstärker).`},2:{does:`Gibt die 5 stärksten Frequenzen mit ihren Noten aus.`,see:`<code>   1765.6 Hz   -31.2 dBFS  A6   +2 cents</code> …`,fix:``},3:{does:`Doppelt so viele Samples: Bins 15,6 Hz auseinander, aber jede Antwort betrachtet 64 ms. <code>fft 256</code>: 62,5-Hz-Bins, 16 ms.`,see:`<code>- FFT 1024: 15.6 Hz per bin, 64 ms window</code>.`,fix:``},4:{does:`Ein 1-s-Sinus auf dem Lautsprecher: die Note, die dem am nächsten liegt, was du in den letzten 2 s gepfiffen hast, sonst A4. S5 liest den Ring direkt, hört also absichtlich seinen eigenen Ton. Ein Doppelklick auf <b>Tuner</b> macht dasselbe.`,see:`<code>- reference A4 = 440.0 Hz, 1 s</code>; der Tuner zeigt A4 mit der Nadel nahe 0.`,fix:`Um viele Cent daneben: Lautsprecher und Mikrofon sind in Ordnung; prüf <code>a4</code>.`},5:{does:`Ein 4-s-Ton von 100 Hz bis 8 kHz auf logarithmischer Skala; der Bildschirm springt zum Wasserfall.`,see:`Eine Diagonale, die den Wasserfall mit gleichmäßiger Steigung hinaufklettert: logarithmische Frequenz, wie bei den Balken.`,fix:``},6:{does:`Stimmt die Notennamen auf A4 = 442 Hz (manche Orchester tun das).`,see:`<code>- A4 = 442.0 Hz</code>; die Cent des Tuners verschieben sich um etwa 8.`,fix:``},7:{does:`Der Punkt folgt deiner Tonhöhe auf einer logarithmischen Skala (600-2500 Hz); halt ihn 1 s im Ring, um zu punkten. Die RGB-LED nimmt die Farbe des Punkts an.`,see:`<code>+ target 1!</code>, ein neuer Ring woanders.`,fix:`Du kommst nicht nach oben: <code>range 500 2000</code>.`},8:{does:`Was diese FFT sehen kann und was nicht.`,see:`Bis 8000 Hz (Nyquist), Bins 31,2 Hz auseinander, 32 ms pro Antwort und die Warnung wegen fehlendem Verstärker.`,fix:``}},panels:{0:{title:`Bau einen Ton, sieh sein Spektrum`,intro:`Bis zu drei Töne plus Rauschen, oben die Samples und unten die Bins der FFT. Nimm den Haken am Fenster weg, um Leakage zu sehen; ändere N, um scharfe Bins gegen eine langsamere Antwort einzutauschen.`},1:{title:`Vom Pfiff zur Note`,intro:`Sechs Schritte, dieselben, die die Tuner-Ansicht 25-mal pro Sekunde macht. Bewege den Pfiff-Regler und sieh, wie die Parabel die Tonhöhe zwischen zwei Bins findet.`},2:{title:`Was der Bildschirm zeigt`,intro:`Vier Ansichten. Klick = nächste, Doppelklick = die Aktion unten links (hold, hold, peaks, target), langer Druck = hold.`}},steps:[`Gleiche Verkabelung wie S1.`,`Flash <code>sound-lab-s5</code>. <b>Checkpoint 1:</b> die beim Boot ausgegebenen Grenzen.`,`Pfeif einen gleichmäßigen Ton auf <b>Bars</b>, dann auf <b>Waterfall</b>. <b>Checkpoint 2:</b> eine helle Linie im Wasserfall.`,`<b>Tuner</b>: Pfeif, bis die Nadel türkis ist. <b>Checkpoint 3:</b> ein Notenname, den du wiederholen kannst.`,`<code>fft 256</code>, <code>fft 1024</code>, zurück zu <code>fft 512</code>. <b>Checkpoint 4:</b> Du hast den Kompromiss gesehen.`,`<b>Steer</b>: 3 Punkte. <b>Checkpoint 5:</b> <code>target 3!</code>.`],note:`Grenzen, die man kennen sollte: Bei 16 000 Samples pro Sekunde ist nichts über 8 kHz sichtbar (Nyquist), und höhere Töne klappen als Fälschungen zurück. Jedes Band lernt seine eigene Ruhe (ein Lüfter brummt tief, ein Laptop fiept hoch), also zeigen die Ansichten dB über dem Grundpegel jedes Bands. Sprache hat viele Obertöne und keinen einzelnen klaren Peak, darum will der Tuner Klarheit ≥ 12 dB: Pfeif oder summ.`},S6:{title:`Sound-Spiele`,heading:`Spiel mit dem, was das Mikrofon hört`,goal:`<span class="snd-parts"><span class="need">KY-037 oder INMP441</span><span class="opt">MAX98357A + Lautsprecher (optional)</span></span>Drei Spiele auf einem Mikrofon, jedes hört nur zu, solange seine Ansicht auf dem Bildschirm ist. <b>Knock</b>: ein Klopfschloss, das sich für deinen geheimen Rhythmus öffnet, schnell oder langsam. <b>Bird</b>: Clap Bird, jedes Klatschen ist ein Flügelschlag. <b>Party</b>: Das Board findet den Beat in Musik und wirft Licht darauf. Mit dem Lautsprecher: Pieptöne, Dings und ein Krach in Clap Bird, das geheime Klopfen wird abgespielt, eine Entsperr-Melodie.`,goalLine:`Öffne das Schloss mit deinem geheimen Klopfen (und scheitere mit einem falschen), komm in Clap Bird an 5 Röhren vorbei und lass die Party dem Tempo eines Songs folgen.`,goalCheck:[`<code>knock set</code> + ein Rhythmus hat ein Geheimnis gespeichert; derselbe Rhythmus, langsamer, öffnet immer noch (LED an GPIO 4, grüne RGB 5 s lang).`,`Ein anderer Rhythmus rüttelt am Vorhängeschloss: <code>locked: the rhythm is off</code>.`,`Clap Bird: ein Score von 5 oder mehr, und <code>best</code> überlebt einen Reset.`,`<b>Party</b> zeigt ein BPM nahe dem Tempo des Songs.`],learn:[`tempounabhängiger Rhythmus`,`Toleranz`,`Spielphysik mit festem Zeitschritt`,`Latenz (Onset vs. Klatschen)`,`Beat-Erkennung`,`Median-Tempo`,`ein Sensor, viele Verwendungen`],pins:{0:{role:`VCC`},1:{role:`MICS +`},2:{role:`AO`},3:{role:`BLK`},4:{role:`RES`},5:{role:`DC`},6:{role:`CS`},7:{role:`SDA`},8:{role:`SCL`},9:{role:`AMP VIN`},10:{role:`GND`},11:{role:`BTN`},12:{role:`MICS G`},13:{role:`SD`},14:{role:`WS`},15:{role:`SCK`},16:{role:`BCLK`},17:{role:`LRC`},18:{role:`BOOT`},19:{role:`DIN`},20:{role:`DO`},21:{role:`AMP G`}},wiring:{title:`Verkabelung: die Mikrofone und der Lautsprecher (verkabel, was das Lab braucht; der Bildschirm bleibt wie in Lektion 03)`,head:[`Modul-Pin`,`ESP32-S3`,`Hinweise`],rows:[[`KY-037 + · G`,`3V3`,`Das analoge Mikrofon. + an den zweiten 3V3-Pin (den ersten hat der Bildschirm), G an GND. <b>Nie 5 V</b>: AO und DO schwingen bis zur Versorgung des Moduls, und die Pins des ESP32-S3 vertragen höchstens 3,3 V.`],[`KY-037 AO`,`GPIO 6`,`Analogausgang: die Spannung des Mikrofons. GPIO 6 ist ADC1-Kanal 5: ADC1 funktioniert weiter, während WLAN an ist, ADC2 nicht.`],[`KY-037 DO`,`GPIO 21`,`Digitalausgang: Der LM393-Komparator meldet high, wenn der Ton lauter ist als die Einstellung des blauen Trimmpotis.`],[`INMP441 VDD · GND`,`3V3`,`Das digitale Mikrofon (I2S). VDD an 3V3 (teil die Steckbrett-Schiene mit dem KY-037), GND an GND. Nur 3,3 V.`],[`INMP441 L/R`,`GND`,`Low = Es spricht im linken Slot, den das Board liest.`],[`INMP441 SCK`,`GPIO 40`,`Der Bit-Takt. Der ESP32 treibt ihn: 16 000 × 64 = 1,024 MHz.`],[`INMP441 WS`,`GPIO 41`,`Word Select: linker Slot / rechter Slot, kippt alle 32 Taktschritte.`],[`INMP441 SD`,`GPIO 42`,`Die Daten, höchstwertiges Bit zuerst. Nach unten gezogen, sodass ein fehlendes Mikrofon als Nullen gelesen wird.`],[`MAX98357A VIN · GND`,`5V`,`Der Lautsprecherverstärker. 5V liefert am meisten (etwa 3 W an 4 Ω); 3V3 geht auch, leiser.`],[`MAX98357A BCLK`,`GPIO 39`,`Bit-Takt des zweiten I2S-Ports (I2S1; das Mikrofon nutzt I2S0, also laufen beide gleichzeitig).`],[`MAX98357A LRC`,`GPIO 38`,`Word Select (links/rechts).`],[`MAX98357A DIN`,`GPIO 47`,`Die Samples, 16 Bit.`],[`MAX98357A GAIN · SD`,`nichts`,`Lass beide unverbunden: 9 dB Verstärkung, und er spielt (links + rechts) / 2.`],[`Lautsprecher (4 Ω, 3 W)`,`amp + / −`,`An der Schraubklemme des Verstärkers: die zwei Drähte des JST-PH2.0-Kabels, rot an +.`],[`Bildschirm (8 Drähte)`,`wie Lektion 03`,`Unverändert. Der Taster an GPIO 5 ist optional: Er macht, was BOOT macht.`]]},commands:{0:{does:`Baut Lab S6 und schreibt es aufs Board, dann öffne den Monitor mit <code>uv run pio device monitor</code>.`,see:`<code>Listening for an INMP441 on the I2S pins...</code>, <code>Microphone: INMP441 (I2S, digital) (mic setting: auto)</code> (oder KY-037), dann <code>Sound lab S6 …</code>, die Befehlsliste und ein Drei-Ton-Hallo aus dem Lautsprecher. Sei eine halbe Sekunde still: <code>- learning the quiet...</code>`,fix:`Falsches Mikrofon gewählt: <code>mic inmp441</code> oder <code>mic ky037</code> (gespeichert, startet neu). Kein Hallo: Der Lautsprecher ist optional; prüf VIN und DIN. „Failed to connect“: Halt BOOT gedrückt, tipp auf RST, lass BOOT los und führ es nochmal aus.`},1:{does:`Das nächste Muster wird das Geheimnis (2-12 Klopfer; 1,5 s Ruhe beenden es). In NVS gespeichert.`,see:`<code>- knock your new secret, then wait 1.5 s</code>, dann <code>+ secret saved: 5 knocks, 1.2 s</code>.`,fix:`<code>a secret needs 2 knocks or more</code>.`},2:{does:`Jedes abgeschlossene Muster wird mit dem Geheimnis verglichen.`,see:`<code>+ OPEN (score 92)</code>: Der Bügel hebt sich, die LED an GPIO 4 und die RGB-LED leuchten 5 s grün. Falsch: <code>x locked: the rhythm is off</code>.`,fix:`Klopfer verpasst: Klopf fest, nah am Mikrofon; <code>knock show</code> gibt beide Rhythmen aus.`},3:{does:`Spielt das Geheimnis als Klicks zu den genauen Zeiten der Klopfer ab (ein esp_timer prüft alle 2 ms).`,see:`<code>- playing the secret: 5 knocks</code> und dein Rhythmus aus dem Lautsprecher.`,fix:`<code>sound is off: sound on</code>.`},4:{does:`Jede Lücke darf um 20 % des Musters abweichen (Standard 12).`,see:`<code>- tolerance 20%</code>.`,fix:``},5:{does:`Clap Bird: eine neue Runde. Ein Klatschen startet sie; jedes Klatschen ist ein Flügelschlag.`,see:`<code>clap to fly!</code>; später <code>+ new best: 6</code>.`,fix:`Flattert spät: Klopf-artige Klatscher (kurz und scharf) lösen den Onset am schnellsten aus.`},6:{does:`Spieltöne auf dem Lautsprecher aus (in NVS gespeichert, Namespace <code>games</code>).`,see:`<code>- game sounds off</code>.`,fix:``},7:{does:`Ein Tick bei jedem Beat. Das Board kann nach jedem Tick etwa 200 ms lang nicht hören (der Echo-Schutz), also werden Beats in diesem Fenster übersprungen. Standardmäßig aus.`,see:`<code>- a tick on every beat (the board can't hear for ~200 ms after it)</code>.`,fix:``},8:{does:`Auf <b>Party</b> lässt jeder Beat eine Farbe aufblitzen, schickt einen Ring hinaus und lässt die RGB-LED leuchten.`,see:`Eine BPM-Zahl (z. B. 120) nach ein paar Beats.`,fix:`Zu viele Beats: <code>party sens 2.0</code>. Zu wenige: <code>party sens 1.3</code>.`}},panels:{0:{title:`Der Abgleich des Klopfschlosses`,intro:`Klopf mit dem Taster (oder der Leertaste). Das erste Muster wird das Geheimnis; die nächsten werden Lücke für Lücke verglichen, jede Lücke als Anteil am ganzen Muster, also spielt das Tempo keine Rolle. Verschieb die Toleranz.`},1:{title:`Was der Bildschirm zeigt`,intro:`Drei Ansichten. Klick = nächste, Doppelklick = die Aktion unten links (knock set, bird, party reset), langer Druck = knock show. In dieser Vorschau ist ein Klick auf den Bildschirm (oder Leertaste) ein Klatschen: Clap Bird ist spielbar.`}},steps:[`Gleiche Verkabelung wie S1. Optional: die LED aus Lektion 02 an GPIO 4 als Riegel des Schlosses.`,`Flash <code>sound-lab-s6</code>. Auf <b>Knock</b>: <code>knock set</code> und klopf einen Rhythmus. <b>Checkpoint 1:</b> Geheimnis gespeichert.`,`Klopf es nochmal, etwas langsamer. <b>Checkpoint 2:</b> OPEN. Dann einen falschen: locked.`,`Klick zu <b>Bird</b> und klatsch. <b>Checkpoint 3:</b> an 5 Röhren vorbei.`,`Klick zu <b>Party</b>, spiel einen Song. <b>Checkpoint 4:</b> Das BPM pendelt sich ein.`],note:`Klopfer sind für den Detektor Klatscher (kurze Knalle, hier bis zu 200 ms). Das Schloss vergleicht Rhythmus, nicht Lautstärke oder Tempo, also ist es ein Spielzeug, keine Sicherheit: Jeder, der dich klopfen hört, kann es nachmachen. Clap Bird lässt seine Physik in festen 1/60-s-Schritten laufen, egal was der Bildschirm tut, also fühlt sich das Spiel bei jeder Bildrate gleich an; es flattert beim Onset (sofort), nicht beim fertigen Klatschen (160 ms später).`},S7:{title:`Lautsprecher`,heading:`Lass das Board spielen: ein Synth auf einem Lautsprecher`,goal:`<span class="snd-parts"><span class="need">MAX98357A + Lautsprecher</span></span>Zahlen gehen über I2S hinaus an den <b>MAX98357A</b>, einen Klasse-D-Verstärker: Er schaltet den Lautsprecher etwa 300 000-mal pro Sekunde ganz an und aus, und wie lange jeder Impuls dauert, folgt der Zahl. Die Membran ist zu träge, um zu folgen, also bewegt sie sich mit dem Mittelwert: der Welle. S7 macht Noten in fünf Klangfarben, Akkorde, Hüllkurven, Melodien und Spieltöne und zeichnet, was du hörst.`,goalLine:`Hör den Unterschied zwischen den fünf Wellen, spiel einen Akkord und eine Melodie, ändere die Hüllkurve, bis eine Note gezupft klingt, und feuere jeden Spielton ab.`,goalCheck:[`<code>beep</code> und der Hallo-Klang kommen bei <code>vol 20</code> aus dem Lautsprecher.`,`Auf <b>Wave</b> zeigt das Spektrum eine Linie für Sinus, ungerade Obertöne für Rechteck, alle für Sägezahn.`,`<code>adsr 1 300 0 50</code> lässt <code>note A4 600</code> gezupft klingen; <code>adsr 300 80 65 300</code> weich.`,`<code>tune korobeiniki</code> spielt, und die Piano Roll scrollt; <code>fx explosion</code> grollt.`],learn:[`I2S-Ausgang`,`Klasse-D-Verstärker`,`Klangfarbe = Obertöne`,`Aliasing bei 16 kHz`,`ADSR vs. Klicks`,`Halbtöne & Akkorde`,`Tempo`,`prozedurale Klänge`,`quadrierte Lautstärke`],pins:{0:{role:`VCC`},1:{role:`MICS +`},2:{role:`AO`},3:{role:`BLK`},4:{role:`RES`},5:{role:`DC`},6:{role:`CS`},7:{role:`SDA`},8:{role:`SCL`},9:{role:`AMP VIN`},10:{role:`GND`},11:{role:`BTN`},12:{role:`MICS G`},13:{role:`SD`},14:{role:`WS`},15:{role:`SCK`},16:{role:`BCLK`},17:{role:`LRC`},18:{role:`BOOT`},19:{role:`DIN`},20:{role:`DO`},21:{role:`AMP G`}},wiring:{title:`Verkabelung: die Mikrofone und der Lautsprecher (verkabel, was das Lab braucht; der Bildschirm bleibt wie in Lektion 03)`,head:[`Modul-Pin`,`ESP32-S3`,`Hinweise`],rows:[[`KY-037 + · G`,`3V3`,`Das analoge Mikrofon. + an den zweiten 3V3-Pin (den ersten hat der Bildschirm), G an GND. <b>Nie 5 V</b>: AO und DO schwingen bis zur Versorgung des Moduls, und die Pins des ESP32-S3 vertragen höchstens 3,3 V.`],[`KY-037 AO`,`GPIO 6`,`Analogausgang: die Spannung des Mikrofons. GPIO 6 ist ADC1-Kanal 5: ADC1 funktioniert weiter, während WLAN an ist, ADC2 nicht.`],[`KY-037 DO`,`GPIO 21`,`Digitalausgang: Der LM393-Komparator meldet high, wenn der Ton lauter ist als die Einstellung des blauen Trimmpotis.`],[`INMP441 VDD · GND`,`3V3`,`Das digitale Mikrofon (I2S). VDD an 3V3 (teil die Steckbrett-Schiene mit dem KY-037), GND an GND. Nur 3,3 V.`],[`INMP441 L/R`,`GND`,`Low = Es spricht im linken Slot, den das Board liest.`],[`INMP441 SCK`,`GPIO 40`,`Der Bit-Takt. Der ESP32 treibt ihn: 16 000 × 64 = 1,024 MHz.`],[`INMP441 WS`,`GPIO 41`,`Word Select: linker Slot / rechter Slot, kippt alle 32 Taktschritte.`],[`INMP441 SD`,`GPIO 42`,`Die Daten, höchstwertiges Bit zuerst. Nach unten gezogen, sodass ein fehlendes Mikrofon als Nullen gelesen wird.`],[`MAX98357A VIN · GND`,`5V`,`Der Lautsprecherverstärker. 5V liefert am meisten (etwa 3 W an 4 Ω); 3V3 geht auch, leiser.`],[`MAX98357A BCLK`,`GPIO 39`,`Bit-Takt des zweiten I2S-Ports (I2S1; das Mikrofon nutzt I2S0, also laufen beide gleichzeitig).`],[`MAX98357A LRC`,`GPIO 38`,`Word Select (links/rechts).`],[`MAX98357A DIN`,`GPIO 47`,`Die Samples, 16 Bit.`],[`MAX98357A GAIN · SD`,`nichts`,`Lass beide unverbunden: 9 dB Verstärkung, und er spielt (links + rechts) / 2.`],[`Lautsprecher (4 Ω, 3 W)`,`amp + / −`,`An der Schraubklemme des Verstärkers: die zwei Drähte des JST-PH2.0-Kabels, rot an +.`],[`Bildschirm (8 Drähte)`,`wie Lektion 03`,`Unverändert. Der Taster an GPIO 5 ist optional: Er macht, was BOOT macht.`]]},commands:{0:{does:`Builds lab S7 and writes it to the board, then open the monitor with <code>uv run pio device monitor</code>.`,see:`<code>Listening for an INMP441 on the I2S pins...</code>, <code>Microphone: INMP441 (I2S, digital) (mic setting: auto)</code> (or KY-037), then <code>Sound lab S7 …</code>, the command list and a three-note hello from the speaker. Stay quiet for half a second: <code>- learning the quiet...</code>`,fix:`Falsches Mikrofon gewählt: <code>mic inmp441</code> oder <code>mic ky037</code> (gespeichert, startet neu). Kein Hallo: Der Lautsprecher ist optional; prüf VIN und DIN. „Failed to connect“: Halt BOOT gedrückt, tipp auf RST, lass BOOT los und führ es nochmal aus.`},1:{does:`Fang leise an: Die Lautstärke wird quadriert, 20 = 4 % der vollen Leistung. In NVS gespeichert (Standard 40).`,see:`<code>- volume 20</code>; dann spielt <code>beep</code> 440 Hz.`,fix:`Stumm: VIN an 5V, DIN an 47, BCLK 39, LRC 38; der Lautsprecher an der Klemme.`},2:{does:`Die Klangfarbe: sine, square, triangle, saw, noise (<code>wave next</code> oder ein Doppelklick auf <b>Wave</b>).`,see:`<code>- wave square</code>; die Linien des Spektrums bei 1, 3, 5… × der Note.`,fix:``},3:{does:`Eine Note (ein Name oder Hz) für 600 ms. Ein Doppelklick auf <b>Envelope</b> macht dasselbe.`,see:`Der Punkt reitet auf der ADSR-Kurve.`,fix:`<code>close to 8 kHz: the limit at 16 kHz</code> über 7 kHz.`},4:{does:`Die Hüllkurve: Attack ms, Decay ms, Sustain %, Release ms (Standard 6 80 65 90). Attack 0 macht einen Klick.`,see:`<code>- adsr 1 300 0 50</code>: eine gezupfte Saite.`,fix:``},5:{does:`Noten zusammen auf einem Ein-Stimmen-Lautsprecher: Das Board addiert sie in einem Puffer (30 s im PSRAM).`,see:`<code>- Am = A4 C5 E5</code>; drei Tasten leuchten auf <b>Keys</b>.`,fix:``},6:{does:`Noten nacheinander mit <code>bpm</code> (Standard 120): /4 Viertel, /8 Achtel, r Pause, . punktiert.`,see:`Die Tasten leuchten der Reihe nach.`,fix:``},7:{does:`twinkle ode happy korobeiniki scale arpeggio. Doppelklick auf <b>Tunes</b> spielt die gewählte; langer Druck wählt die nächste.`,see:`Die Piano Roll scrollt am bernsteinfarbenen Playhead vorbei.`,fix:``},8:{does:`Spieltöne aus Rezepten: Sweeps, Rauschen, ein sich schließender Filter.`,see:`Die ganze Wellenform auf <b>Fx</b>, ein Playhead, der sie durchquert.`,fix:``},9:{does:`Stille.`,see:`Die Wellen im Kopf hören auf.`,fix:``}},panels:{0:{title:`Von Zahlen zur bewegten Membran`,intro:`Was mit einem Sample passiert, nachdem das Board es berechnet hat, warum der Lautstärkeregler quadriert ist und der Echo-Schutz, der das Mikrofon davon abhält, lautsprecherbedingt Klatscher zu hören.`},1:{title:`Ein Synth zum Spielen`,intro:`Dieselben Wellen und Hüllkurven wie auf dem Board. Wähl eine Welle, drück eine Taste, um sie in diesem Browser zu hören (leise; nichts spielt, bis du drückst), und zieh die Griffe der Hüllkurve. Die roten Balken sind Obertöne, die das Board bei 16 kHz nicht erzeugen kann: Sie klappen als falsche Töne zurück.`},2:{title:`Was der Bildschirm zeigt`,intro:`Fünf Ansichten. Klick = nächste, Doppelklick = die Aktion unten links. Keys: langer Druck = der nächste Akkord. Tunes und fx: langer Druck wählt die nächste. Sonst stoppt ein langer Druck den Ton.`}},steps:[`Verkabel den MAX98357A: VIN → 5V, GND, BCLK → 39, LRC → 38, DIN → 47; der Lautsprecher an seiner Schraubklemme (rot an +). GAIN und SD bleiben unverbunden. Kein Mikrofon nötig.`,`Flash <code>sound-lab-s7</code>. <b>Checkpoint 1:</b> der Hallo-Klang und <code>start quiet: vol 20, then raise it</code>.`,`<code>vol 20</code>, dann fünfmal <code>wave next</code> mit <code>note A4</code>. <b>Checkpoint 2:</b> fünf Klangfarben, fünf Spektren.`,`<code>adsr 1 300 0 50</code>, <code>note A4 600</code>; dann <code>adsr 0 0 100 0</code>. <b>Checkpoint 3:</b> Du hörst den Klick, den die Hüllkurve entfernt.`,`<code>chord Am</code>, <code>tune ode</code>, <code>fx coin</code>. <b>Checkpoint 4:</b> alle drei spielen.`],note:`Ein Lautsprecher, ein Stream: Akkorde und Melodien werden zuerst ins PSRAM gerendert (bis zu 30 s) und dann abgespielt. Bei 16 000 Samples pro Sekunde existiert nichts über 8 kHz, also klappen die hohen Obertöne eines Rechtecks oder Sägezahns als falsche Frequenzen nach unten: ein leichtes Kratzen bei hohen Noten, die ehrliche Grenze eines einfachen Synths. Jedes andere Sound-Lab nutzt denselben Lautsprecher für seine Klänge, und der Echo-Schutz hält seine Detektoren taub, solange er spielt.`},S8:{title:`Voice FX`,heading:`Ein Papagei, der dich nachspricht, und eine Live-Roboterstimme`,goal:`<span class="snd-parts"><span class="need">INMP441</span><span class="need">MAX98357A + Lautsprecher</span></span>Mikrofon rein, Lautsprecher raus. Sag etwas, und der Papagei sagt es zurück: normal, als <b>Chipmunk</b> (1,5-mal schneller), als <b>Giant</b> (0,7-mal), als <b>Robot</b> (Ringmodulator + 6-Bit-Crunch), mit <b>Echo</b> oder <b>Reverse</b>. Dann Live-Effekte: ein Echo, in das du sprichst, eine Roboterstimme. Der Papagei ist wie S4 sprachgesteuert (12 dB, 0,3 s Pre-Roll, 0,7 s Hold, höchstens 6 s) und hört sich nie selbst.`,goalLine:`Lass den Papagei dich in drei Stimmen wiederholen, sprich durch das Live-Echo ohne Heulen und erkläre, warum ein Chipmunk schnell spricht.`,goalCheck:[`Du hast ein Wort gesagt, und der Papagei hat mit der Chipmunk-Stimme geantwortet; <code>fx giant</code> + <code>again</code> antwortete tief und langsam.`,`<b>Echo</b>-Ansicht: <code>echo on</code>, ein Klatschen kommt als verklingende Wiederholungen zurück, Latenz etwa 60-80 ms.`,`Du hast ein Heulen provoziert (und der Wächter hat es gestoppt), indem du den Lautsprecher aufs Mikrofon gerichtet hast: <code>Howl! Move the speaker away or turn it down</code>.`],learn:[`Resampling = Tonhöhe + Tempo`,`Ringmodulation f±c`,`Bitcrush`,`Delay + Feedback`,`Schleifenverstärkung < 1`,`Heul-Erkennung`,`Latenzbudget`,`Echo-Schutz`],pins:{0:{role:`VCC`},1:{role:`MICS +`},2:{role:`AO`},3:{role:`BLK`},4:{role:`RES`},5:{role:`DC`},6:{role:`CS`},7:{role:`SDA`},8:{role:`SCL`},9:{role:`AMP VIN`},10:{role:`GND`},11:{role:`BTN`},12:{role:`MICS G`},13:{role:`SD`},14:{role:`WS`},15:{role:`SCK`},16:{role:`BCLK`},17:{role:`LRC`},18:{role:`BOOT`},19:{role:`DIN`},20:{role:`DO`},21:{role:`AMP G`}},wiring:{title:`Verkabelung: die Mikrofone und der Lautsprecher (verkabel, was das Lab braucht; der Bildschirm bleibt wie in Lektion 03)`,head:[`Modul-Pin`,`ESP32-S3`,`Hinweise`],rows:[[`KY-037 + · G`,`3V3`,`Das analoge Mikrofon. + an den zweiten 3V3-Pin (den ersten hat der Bildschirm), G an GND. <b>Nie 5 V</b>: AO und DO schwingen bis zur Versorgung des Moduls, und die Pins des ESP32-S3 vertragen höchstens 3,3 V.`],[`KY-037 AO`,`GPIO 6`,`Analogausgang: die Spannung des Mikrofons. GPIO 6 ist ADC1-Kanal 5: ADC1 funktioniert weiter, während WLAN an ist, ADC2 nicht.`],[`KY-037 DO`,`GPIO 21`,`Digitalausgang: Der LM393-Komparator meldet high, wenn der Ton lauter ist als die Einstellung des blauen Trimmpotis.`],[`INMP441 VDD · GND`,`3V3`,`Das digitale Mikrofon (I2S). VDD an 3V3 (teil die Steckbrett-Schiene mit dem KY-037), GND an GND. Nur 3,3 V.`],[`INMP441 L/R`,`GND`,`Low = Es spricht im linken Slot, den das Board liest.`],[`INMP441 SCK`,`GPIO 40`,`Der Bit-Takt. Der ESP32 treibt ihn: 16 000 × 64 = 1,024 MHz.`],[`INMP441 WS`,`GPIO 41`,`Word Select: linker Slot / rechter Slot, kippt alle 32 Taktschritte.`],[`INMP441 SD`,`GPIO 42`,`Die Daten, höchstwertiges Bit zuerst. Nach unten gezogen, sodass ein fehlendes Mikrofon als Nullen gelesen wird.`],[`MAX98357A VIN · GND`,`5V`,`Der Lautsprecherverstärker. 5V liefert am meisten (etwa 3 W an 4 Ω); 3V3 geht auch, leiser.`],[`MAX98357A BCLK`,`GPIO 39`,`Bit-Takt des zweiten I2S-Ports (I2S1; das Mikrofon nutzt I2S0, also laufen beide gleichzeitig).`],[`MAX98357A LRC`,`GPIO 38`,`Word Select (links/rechts).`],[`MAX98357A DIN`,`GPIO 47`,`Die Samples, 16 Bit.`],[`MAX98357A GAIN · SD`,`nichts`,`Lass beide unverbunden: 9 dB Verstärkung, und er spielt (links + rechts) / 2.`],[`Lautsprecher (4 Ω, 3 W)`,`amp + / −`,`An der Schraubklemme des Verstärkers: die zwei Drähte des JST-PH2.0-Kabels, rot an +.`],[`Bildschirm (8 Drähte)`,`wie Lektion 03`,`Unverändert. Der Taster an GPIO 5 ist optional: Er macht, was BOOT macht.`]]},commands:{0:{does:`Builds lab S8 and writes it to the board, then open the monitor with <code>uv run pio device monitor</code>.`,see:`<code>Listening for an INMP441 on the I2S pins...</code>, <code>Microphone: INMP441 (I2S, digital) (mic setting: auto)</code> (or KY-037), then <code>Sound lab S8 …</code>, the command list and a three-note hello from the speaker. Stay quiet for half a second: <code>- learning the quiet...</code>`,fix:`Falsches Mikrofon gewählt: <code>mic inmp441</code> oder <code>mic ky037</code> (gespeichert, startet neu). Kein Hallo: Der Lautsprecher ist optional; prüf VIN und DIN. „Failed to connect“: Halt BOOT gedrückt, tipp auf RST, lass BOOT los und führ es nochmal aus.`},1:{does:`Halt es niedrig: Das Mikrofon hört den Lautsprecher.`,see:`<code>- volume 25</code>.`,fix:`Mit dem KY-037: <code>KY-037: it works, but an INMP441 sounds much clearer</code>.`},2:{does:`Lauter als 12 dB über der Ruhe startet eine Aufnahme mit 0,3 s von davor; 0,7 s Ruhe beenden sie; dann spielt es sie mit der Stimme ab.`,see:`Die Sprechblase: <code>I'm listening...</code>, REC, dann <code>Squawk!</code> mit beweglichem Schnabel; <code>+ chipmunk, 1.4 s, x9 louder</code>.`,fix:`<code>too short: a bang, not a word</code>: Sprich etwas länger. Startet nie: <code>trigger 8</code>.`},3:{does:`Die Stimme des Papageis: normal chipmunk giant robot echo reverse. Doppelklick auf <b>Parrot</b>.`,see:`<code>- voice: robot (ring modulator + bitcrush)</code>.`,fix:``},4:{does:`Sagt die letzte Aufnahme nochmal mit der aktuellen Stimme (Doppelklick auf <b>Scope</b>).`,see:`Dieselben Worte, eine andere Stimme.`,fix:`<code>nothing recorded yet: say something first</code>.`},5:{does:`Live: Mikrofon → Delay-Line → Lautsprecher. <code>delay 120</code> (20-500 ms), <code>feedback 60</code> (0-70 %). Braucht das Mikrofon mit 16 000 Hz.`,see:`<code>! live echo: speaker away from the mic, volume low</code>; die Taps eines Klatschens in der <b>Echo</b>-Ansicht und eine Latenz von ~60-80 ms.`,fix:`Ein Heulen: Der Wächter stoppt es mit einem tiefen Nein. Dreh den Lautsprecher weg, senk <code>vol</code> oder <code>feedback</code>.`},6:{does:`Live: deine Stimme × eine langsame Sinuswelle (<code>carrier 50</code>, 10-300 Hz) + Crunch. Jede Frequenz f wird zu f − c und f + c.`,see:`Der Mund des Roboters leuchtet mit dem, was herauskommt. <code>carrier 200</code> klingt wie eine Glocke.`,fix:``}},panels:{0:{title:`Der Papagei, in deinem Browser`,intro:`Dieselben Effekte wie in fx.h, auf dieser Seite. Eine Beispielstimme ist geladen; deine eigene aufzunehmen ist optional und startet nur, wenn du den Knopf drückst (3 s, eine rote Anzeige während der Aufnahme, nichts verlässt die Seite).`},1:{title:`Was der Bildschirm zeigt`,intro:`Vier Ansichten. Klick = nächste, Doppelklick = die Aktion unten links (fx next, echo, robot, again), langer Druck = von Hand aufnehmen / stopp.`}},steps:[`Verkabel das INMP441 (VDD 3V3, GND, L/R → GND, SCK 40, WS 41, SD 42) und den MAX98357A + Lautsprecher wie in S7. Richte den Lautsprecher vom Mikrofon weg.`,`Flash <code>sound-lab-s8</code>, <code>vol 25</code>. <b>Checkpoint 1:</b> <code>Microphone: INMP441</code> und der Papagei sagt „Say something!“.`,`Sag einen kurzen Satz. <b>Checkpoint 2:</b> Der Chipmunk antwortet.`,`<code>fx giant</code>, <code>again</code>; <code>fx reverse</code>, <code>again</code>. <b>Checkpoint 3:</b> Du kannst sagen, warum der Giant langsam ist.`,`<code>echo on</code>, klatsch. <b>Checkpoint 4:</b> verklingende Wiederholungen; <code>echo off</code>.`,`<code>robot on</code>, sprich. <b>Checkpoint 5:</b> eine Roboterstimme; <code>robot off</code>.`],note:`Die Geschwindigkeit einer Aufnahme zu ändern ändert ihre Tonhöhe und ihre Länge zugleich: Darum spricht der Chipmunk schnell. Die Geschwindigkeit beizubehalten und dabei die Tonhöhe zu verschieben braucht viel mehr DSP (Grains oder ein Phasenvocoder). Feedback: Kommt das, was das Mikrofon hört, lauter zurück, als es hinausging (Schleifenverstärkung über 1), dreht es sich im Kreis: das Heulen. Der Wächter schneidet den Live-Effekt ab, wenn der Pegel weiter steigt (9 dB innerhalb von 300 ms) oder über −12 dBFS bleibt. Latenz = ein Bildschirm-Frame Verarbeitung + die Warteschlange des Lautsprechers + sein 16-ms-DMA-Block.`}};export{e as default};
